function safeRows(nodeName) {
  try { return $(nodeName).all().map(function (i) { return i.json || {}; }); }
  catch (e) { return []; }
}
function opts(arr) { return { values: arr.map(function (o) { return { option: String(o) }; }) }; }
function fa2en(s) { return String(s == null ? '' : s).replace(/[۰-۹]/g, function (d) { return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d); }); }
function normTime(s) { return fa2en(s).replace(/\s+/g, '').replace('،', '').trim(); }

const todayISO = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Tehran' });

const settingsRows = safeRows('خواندن تنظیمات');
const settings = {};
for (let i = 0; i < settingsRows.length; i++) {
  const k = settingsRows[i]['کلید'];
  if (k) settings[String(k).trim()] = settingsRows[i]['مقدار'];
}

const isLive = function (r) {
  const s = String(r['وضعیت'] || '').trim();
  return s !== 'غیرفعال' && s !== 'حذف';
};

const teachers = safeRows('خواندن مدرسین').filter(function (r) { return r['کد_مدرس'] && isLive(r); });
const classes = safeRows('خواندن کلاس‌ها').filter(function (r) { return r['کد_کلاس'] && isLive(r); });

const classOptions = classes.map(function (c) {
  return c['کد_کلاس'] + ' — ' + (c['نام_کلاس'] || '') + ' (' + (c['نوع_کلاس'] || '') + ')';
});
const teacherOptions = teachers.map(function (t) {
  return t['کد_مدرس'] + ' — ' + (t['نام_مدرس'] || '');
});

function classField() {
  return classOptions.length
    ? { fieldLabel: 'کلاس', fieldType: 'dropdown', requiredField: true, fieldOptions: opts(classOptions) }
    : { fieldLabel: 'کلاس (کد یا نام)', fieldType: 'text', requiredField: true, placeholder: 'هنوز کلاسی در شیت «کلاس‌ها» ثبت نشده — کد یا نام را بنویسید' };
}
function teacherField() {
  return teacherOptions.length
    ? { fieldLabel: 'نام مدرس', fieldType: 'dropdown', requiredField: false, fieldOptions: opts(teacherOptions) }
    : { fieldLabel: 'نام مدرس', fieldType: 'text', requiredField: false, placeholder: 'اگر کلاس در شیت ثبت شده، خالی بگذارید' };
}
function placeField() {
  return { fieldLabel: 'مکان برگزاری', fieldType: 'dropdown', requiredField: true, fieldOptions: opts(['کلاس ۱', 'کلاس ۲', 'آنلاین', 'ترکیبی', 'سایر']) };
}

const DAYS = ['شنبه', 'یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه'];

const formSession = [
  { fieldLabel: 'تاریخ برگزاری', fieldType: 'date', requiredField: true, defaultValue: todayISO },
  classField(),
  placeField(),
  { fieldLabel: 'ساعت', fieldType: 'text', requiredField: false, placeholder: 'مثلاً 16:00 تا 17:30' },
  { fieldLabel: 'تعداد جلسه', fieldType: 'number', requiredField: true, defaultValue: '1' },
  { fieldLabel: 'تعداد فراگیر حاضر', fieldType: 'number', requiredField: false },
  { fieldLabel: 'وضعیت', fieldType: 'radio', requiredField: true, fieldOptions: opts(['برگزار شد', 'لغو شد', 'جبرانی']), defaultValue: 'برگزار شد' },
  { fieldLabel: 'توضیح', fieldType: 'textarea', requiredField: false },
];

const formWeekly = [
  { fieldLabel: 'نام فراگیر', fieldType: 'text', requiredField: true },
  { fieldLabel: 'موبایل فراگیر', fieldType: 'text', requiredField: false, placeholder: '۰۹۱۲۳۴۵۶۷۸۹' },
  classField(),
  { fieldLabel: 'نوع کلاس', fieldType: 'radio', requiredField: true, fieldOptions: opts(['حضوری', 'آنلاین', 'ترکیبی']), defaultValue: 'حضوری' },
  { fieldLabel: 'قالب کلاس', fieldType: 'radio', requiredField: true, fieldOptions: opts(['خصوصی', 'نیمه‌خصوصی', 'گروهی', 'کارگاه']), defaultValue: 'گروهی' },
  placeField(),
  teacherField(),
  { fieldLabel: 'تعداد روز در هفته', fieldType: 'dropdown', requiredField: true, fieldOptions: opts(['۱', '۲', '۳', '۴', '۵', '۶', '۷']), defaultValue: '۱' },
  { fieldLabel: 'تاریخ شروع', fieldType: 'date', requiredField: true, defaultValue: todayISO },
  { fieldLabel: 'وضعیت', fieldType: 'radio', requiredField: true, fieldOptions: opts(['فعال', 'متوقف', 'تمام شده', 'جبرانی']), defaultValue: 'فعال' },
  { fieldLabel: 'توضیح', fieldType: 'textarea', requiredField: false },
];

// --- پیش‌نمایش کلاس‌های ثبت‌شده (برای پرهیز از ثبت تکراری) ---
const weeklyRows = safeRows('خواندن برنامه هفتگی').filter(function (r) {
  return isLive(r) && (r['نام_فراگیر'] || r['کد_کلاس']);
});
const slotMap = {};
const slotOrder = [];
for (let i = 0; i < weeklyRows.length; i++) {
  const r = weeklyRows[i];
  const key = [String(r['کد_کلاس'] || '').trim(), String(r['روز_هفته'] || '').trim(), normTime(r['ساعت_شروع']), String(r['مکان'] || '').trim()].join('|');
  if (!slotMap[key]) {
    slotMap[key] = {
      cls: String(r['نام_کلاس'] || r['کد_کلاس'] || '').trim(),
      day: String(r['روز_هفته'] || '').trim(),
      time: String(r['ساعت_شروع'] || '').trim(),
      place: String(r['مکان'] || '').trim(),
      group: String(r['شماره_گروه'] || '').trim(),
      names: [],
    };
    slotOrder.push(key);
  }
  const nm = String(r['نام_فراگیر'] || '').trim();
  if (nm && slotMap[key].names.indexOf(nm) < 0) slotMap[key].names.push(nm);
  if (!slotMap[key].group && r['شماره_گروه']) slotMap[key].group = String(r['شماره_گروه']).trim();
}

let previewText;
if (!slotOrder.length) {
  previewText = 'اطلاعات کلاس فراگیر را پر کنید. هنوز هیچ کلاسی در برنامهٔ هفتگی ثبت نشده است — این اولین ثبت است.';
} else {
  const lines = ['📋 کلاس‌های ثبت‌شدهٔ فعلی — برای پرهیز از ثبت تکراری اول این فهرست را ببینید:', ''];
  const cap = Math.min(slotOrder.length, 40);
  for (let i = 0; i < cap; i++) {
    const s = slotMap[slotOrder[i]];
    const g = s.group ? ('گروه ' + s.group) : 'بدون گروه';
    const cnt = s.names.length;
    const who = s.names.length ? (s.names.join('، ') + (cnt > 1 ? (' (' + cnt + ' نفر — کلاس گروهی)') : '')) : '—';
    lines.push('• ' + s.cls + ' — ' + s.day + ' ' + s.time + ' — ' + s.place + ' — ' + g + ': ' + who);
  }
  if (slotOrder.length > cap) lines.push('… و ' + (slotOrder.length - cap) + ' مورد دیگر.');
  lines.push('');
  lines.push('اگر همین فراگیر در همین روز/ساعت/کلاس از قبل هست، دوباره ثبت نکنید. اگر فراگیرِ تازه‌ای در یک روز/ساعت مشترک است، سیستم خودش او را در همان شمارهٔ گروه ثبت می‌کند.');
  previewText = lines.join('\n');
}

const ft = $('فرم ثبت سریع').first().json;
const kind = String(ft['نوع_ثبت'] || '');

return [{
  json: {
    kind: kind,
    todayISO: todayISO,
    settings: settings,
    teachers: teachers,
    classes: classes,
    previewText: previewText,
    formSessionJson: JSON.stringify(formSession),
    formWeeklyJson: JSON.stringify(formWeekly),
  },
}];

function div(a,b){return ~~(a/b);}
function mod(a,b){return a-~~(a/b)*b;}
function jalCal(jy){var bk=[-61,9,38,199,426,686,756,818,1111,1181,1210,1635,2060,2097,2192,2262,2324,2394,2456,3178],bl=bk.length,gy=jy+621,leapJ=-14,jp=bk[0],jm,jump=0,leap,n,i;if(jy<jp||jy>=bk[bl-1])throw new Error('سال شمسی نامعتبر');for(i=1;i<bl;i++){jm=bk[i];jump=jm-jp;if(jy<jm)break;leapJ=leapJ+div(jump,33)*8+div(mod(jump,33),4);jp=jm;}n=jy-jp;leapJ=leapJ+div(n,33)*8+div(mod(n,33)+3,4);if(mod(jump,33)===4&&jump-n===4)leapJ+=1;var leapG=div(gy,4)-div((div(gy,100)+1)*3,4)-150,march=20+leapJ-leapG;if(jump-n<6)n=n-jump+div(jump+4,33)*33;leap=mod(mod(n+1,33)-1,4);if(leap===-1)leap=4;return{leap:leap,gy:gy,march:march};}
function g2d(gy,gm,gd){var d=div((gy+div(gm-8,6)+100100)*1461,4)+div(153*mod(gm+9,12)+2,5)+gd-34840408;d=d-div(div(gy+100100+div(gm-8,6),100)*3,4)+752;return d;}
function d2g(jdn){var j=4*jdn+139361631;j=j+div(div(4*jdn+183187720,146097)*3,4)*4-3908;var i=div(mod(j,1461),4)*5+308,gd=div(mod(i,153),5)+1,gm=mod(div(i,153),12)+1,gy=div(j,1461)-100100+div(8-gm,6);return{gy:gy,gm:gm,gd:gd};}
function d2j(jdn){var gy=d2g(jdn).gy,jy=gy-621,r=jalCal(jy),jdn1f=g2d(gy,3,r.march),k=jdn-jdn1f,jm,jd;if(k>=0){if(k<=185){jm=1+div(k,31);jd=mod(k,31)+1;return{jy:jy,jm:jm,jd:jd};}k-=186;}else{jy-=1;k+=179;if(r.leap===1)k+=1;}jm=7+div(k,30);jd=mod(k,30)+1;return{jy:jy,jm:jm,jd:jd};}
function pad(n){return String(n).length<2?'0'+n:String(n);}
function toJ(iso){var p=String(iso).slice(0,10).split('-');return d2j(g2d(+p[0],+p[1],+p[2]));}
function toNum(v){var s=String(v==null?'':v).replace(/[۰-۹]/g,function(d){return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d);}).replace(/[٫٬،,_\s]/g,'').replace(/\.(?=\d{3}(\D|$))/g,'').replace(/[^0-9.\-]/g,'');var n=Number(s);return Number.isFinite(n)?n:0;}

const WEEK = ['یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'];

const f = $input.first().json;
const prep = $('آماده‌سازی فرم').first().json;

const iso = String(f['تاریخ برگزاری'] || f['تاریخ'] || prep.todayISO).slice(0, 10);
const j = toJ(iso);
const weekday = WEEK[new Date(iso + 'T12:00:00Z').getUTCDay()];

const classLabel = String(f['کلاس'] || f['کلاس (کد یا نام)'] || '');
const classCode = classLabel.indexOf(' — ') > 0 ? classLabel.split(' — ')[0].trim() : classLabel.trim();
const cls = (prep.classes || []).filter(function (c) { return String(c['کد_کلاس']).trim() === classCode; })[0]
         || (prep.classes || []).filter(function (c) { return String(c['نام_کلاس']).trim() === classCode; })[0]
         || {};
const teacher = (prep.teachers || []).filter(function (t) { return t['کد_مدرس'] === cls['کد_مدرس']; })[0] || {};

const id = 'SC-' + j.jy + pad(j.jm) + '-' + Date.now().toString(36).slice(-5).toUpperCase();

return [{
  json: {
    'شناسه': id,
    'تاریخ_شمسی': j.jy + '/' + pad(j.jm) + '/' + pad(j.jd),
    'تاریخ_میلادی': iso,
    'سال_شمسی': j.jy,
    'ماه_شمسی': j.jm,
    'روز_هفته': weekday,
    'کد_کلاس': cls['کد_کلاس'] || classCode,
    'نام_کلاس': cls['نام_کلاس'] || classLabel,
    'نوع_کلاس': String(cls['نوع_کلاس'] || ''),
    'کد_مدرس': cls['کد_مدرس'] || '',
    'نام_مدرس': teacher['نام_مدرس'] || '',
    'مکان': String(f['مکان برگزاری'] || ''),
    'ساعت': String(f['ساعت'] || ''),
    'تعداد_جلسه': toNum(f['تعداد جلسه']) || 1,
    'تعداد_فراگیر': toNum(f['تعداد فراگیر حاضر']),
    'وضعیت': String(f['وضعیت'] || 'برگزار شد'),
    'توضیح': String(f['توضیح'] || ''),
    'منبع': 'فرم',
    'زمان_ثبت': new Date().toISOString(),
  },
}];

