function fa2en(s){return String(s==null?'':s).replace(/[۰-۹]/g,function(d){return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d);});}
function normTime(s){return fa2en(s).replace(/\s+/g,'').replace('،','').trim();}
function normName(s){return String(s==null?'':s).replace(/\s+/g,' ').trim();}
function normMobile(s){return fa2en(s).replace(/\D/g,'');}
function safeRows(nodeName){try{return $(nodeName).all().map(function(i){return i.json||{};});}catch(e){return [];}}

const p1 = $('فرم برنامهٔ شاگرد').first().json;
const p2 = $input.first().json;
const prep = $('آماده‌سازی فرم').first().json;

let nDays = 1;
try { nDays = $('ساخت روزهای هفته').first().json.nDays || 1; } catch (e) { nDays = 1; }

const iso = String(p1['تاریخ شروع'] || prep.todayISO).slice(0, 10);
const j = toJ(iso);
const startShamsi = j.jy + '/' + pad(j.jm) + '/' + pad(j.jd);

const classLabel = String(p1['کلاس'] || p1['کلاس (کد یا نام)'] || '');
const classCode = classLabel.indexOf(' — ') > 0 ? classLabel.split(' — ')[0].trim() : classLabel.trim();
const cls = (prep.classes || []).filter(function (c) { return String(c['کد_کلاس']).trim() === classCode; })[0]
         || (prep.classes || []).filter(function (c) { return String(c['نام_کلاس']).trim() === classCode; })[0]
         || {};

const tLabel = String(p1['نام مدرس'] || '');
const tCode = tLabel.indexOf(' — ') > 0 ? tLabel.split(' — ')[0].trim() : '';
let teacher = null;
if (cls['کد_مدرس']) teacher = (prep.teachers || []).filter(function (t) { return t['کد_مدرس'] === cls['کد_مدرس']; })[0];
if (!teacher && tCode) teacher = (prep.teachers || []).filter(function (t) { return String(t['کد_مدرس']).trim() === tCode; })[0];
if (!teacher && tLabel) teacher = (prep.teachers || []).filter(function (t) { return String(t['نام_مدرس']).trim() === tLabel || String(t['نام_مدرس']).indexOf(tLabel) >= 0; })[0];
teacher = teacher || {};
const teacherName = teacher['نام_مدرس'] || (tLabel.indexOf(' — ') > 0 ? tLabel.split(' — ')[1].trim() : tLabel);

const stamp = Date.now().toString(36).slice(-5).toUpperCase();

const clsCode = cls['کد_کلاس'] || classCode;
const clsName = cls['نام_کلاس'] || classLabel;
const place = String(p1['مکان برگزاری'] || '');
const learnerName = normName(p1['نام فراگیر']);
const learnerMobile = normMobile(p1['موبایل فراگیر']);
const memberKey = learnerName + '|' + learnerMobile;

// --- ساخت نقشهٔ اسلات‌های موجود از برنامهٔ هفتگی ---
function slotKeyOf(clsC, day, startT, plc) {
  return [String(clsC || '').trim(), String(day || '').trim(), normTime(startT), String(plc || '').trim()].join('|');
}
const existingRows = safeRows('خواندن برنامه هفتگی').filter(function (r) {
  const st = String(r['وضعیت'] || '').trim();
  return st !== 'غیرفعال' && st !== 'حذف' && (r['نام_فراگیر'] || r['کد_کلاس']);
});
const slots = {};
let maxGroup = 0;
for (let i = 0; i < existingRows.length; i++) {
  const r = existingRows[i];
  const key = slotKeyOf(r['کد_کلاس'], r['روز_هفته'], r['ساعت_شروع'], r['مکان']);
  if (!slots[key]) slots[key] = { group: '', members: {}, count: 0 };
  const g = String(r['شماره_گروه'] || '').trim();
  if (g && !slots[key].group) slots[key].group = g;
  const gm = g.match(/(\d+)/);
  if (gm) { const gn = parseInt(gm[1], 10); if (gn > maxGroup) maxGroup = gn; }
  const mk = normName(r['نام_فراگیر']) + '|' + normMobile(r['موبایل_فراگیر']);
  if (!slots[key].members[mk]) { slots[key].members[mk] = true; slots[key].count++; }
}

const shared = {
  'نام_فراگیر': String(p1['نام فراگیر'] || ''),
  'موبایل_فراگیر': String(p1['موبایل فراگیر'] || ''),
  'کد_کلاس': clsCode,
  'نام_کلاس': clsName,
  'نوع_کلاس': String(p1['نوع کلاس'] || cls['نوع_کلاس'] || ''),
  'قالب_کلاس': String(p1['قالب کلاس'] || ''),
  'مکان': place,
  'کد_مدرس': teacher['کد_مدرس'] || '',
  'نام_مدرس': teacherName || '',
  'تاریخ_شروع': startShamsi,
  'وضعیت': String(p1['وضعیت'] || 'فعال'),
  'توضیح': String(p1['توضیح'] || ''),
  'منبع': 'فرم',
};

function ensureGroup(key) {
  if (!slots[key]) slots[key] = { group: '', members: {}, count: 0 };
  if (!slots[key].group) { maxGroup++; slots[key].group = 'G-' + maxGroup; }
  return slots[key].group;
}

const written = [];   // {day, time, group, count}
const dups = [];      // {day, time}
const out = [];

for (let i = 1; i <= nDays; i++) {
  const day = String(p2['روز ' + i + ' — روز هفته'] || '');
  const st = String(p2['روز ' + i + ' — ساعت شروع'] || '');
  const en = String(p2['روز ' + i + ' — ساعت پایان'] || '');
  if (!day && !st) continue;

  const key = slotKeyOf(clsCode, day, st, place);
  const isDup = slots[key] && slots[key].members[memberKey];

  if (isDup) {
    dups.push({ day: day, time: st });
    out.push({ json: Object.assign({}, shared, {
      'شناسه': 'WP-' + j.jy + pad(j.jm) + '-' + stamp + '-' + i,
      'روز_هفته': day, 'ساعت_شروع': st, 'ساعت_پایان': en,
      'شماره_گروه': (slots[key] && slots[key].group) || '',
      'زمان_ثبت': new Date().toISOString(),
      '_write': false,
    }) });
    continue;
  }

  const group = ensureGroup(key);
  slots[key].members[memberKey] = true;
  slots[key].count++;
  written.push({ day: day, time: st, group: group, count: slots[key].count });

  out.push({ json: Object.assign({}, shared, {
    'شناسه': 'WP-' + j.jy + pad(j.jm) + '-' + stamp + '-' + i,
    'روز_هفته': day, 'ساعت_شروع': st, 'ساعت_پایان': en,
    'شماره_گروه': group,
    'زمان_ثبت': new Date().toISOString(),
    '_write': true,
  }) });
}

if (!out.length) {
  const key = slotKeyOf(clsCode, '', '', place);
  const group = ensureGroup(key);
  written.push({ day: '', time: '', group: group, count: slots[key].count + 1 });
  out.push({ json: Object.assign({}, shared, {
    'شناسه': 'WP-' + j.jy + pad(j.jm) + '-' + stamp,
    'روز_هفته': '', 'ساعت_شروع': '', 'ساعت_پایان': '',
    'شماره_گروه': group,
    'زمان_ثبت': new Date().toISOString(),
    '_write': true,
  }) });
}

// --- پیام نتیجه ---
const msg = [];
msg.push('فراگیر: ' + (shared['نام_فراگیر'] || '—') + ' — کلاس: ' + clsName);
if (written.length) {
  msg.push('');
  msg.push('✅ ثبت شد:');
  for (let i = 0; i < written.length; i++) {
    const w = written[i];
    const grp = w.count > 1 ? (w.group + ' (کلاس گروهی — ' + w.count + ' نفر)') : (w.group + ' (فعلاً ۱ نفر)');
    msg.push('• ' + (w.day ? (w.day + ' ') : '') + (w.time || '') + ' → گروه ' + grp);
  }
}
if (dups.length) {
  msg.push('');
  msg.push('⚠️ این موارد از قبل برای همین فراگیر ثبت شده بود و دوباره ثبت نشد:');
  for (let i = 0; i < dups.length; i++) {
    msg.push('• ' + (dups[i].day ? (dups[i].day + ' ') : '') + (dups[i].time || ''));
  }
}
msg.push('');
msg.push('برای ثبت مورد بعدی صفحه را دوباره باز کنید.');
const summary = msg.join('\n');

for (let i = 0; i < out.length; i++) { out[i].json['_پیام'] = summary; }

return out;

function fa2en(s) {
  return String(s == null ? '' : s).replace(/[۰-۹]/g, function (d) { return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d); });
}
function opts(arr) { return { values: arr.map(function (o) { return { option: String(o) }; }) }; }

const f = $('فرم برنامهٔ شاگرد').first().json;
let n = parseInt(fa2en(String(f['تعداد روز در هفته'] || '1')), 10);
if (!Number.isFinite(n) || n < 1) n = 1;
if (n > 7) n = 7;

const DAYS = ['شنبه', 'یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه'];

const fields = [];
for (let i = 1; i <= n; i++) {
  fields.push({ fieldLabel: 'روز ' + i + ' — روز هفته', fieldType: 'dropdown', requiredField: true, fieldOptions: opts(DAYS) });
  fields.push({ fieldLabel: 'روز ' + i + ' — ساعت شروع', fieldType: 'text', requiredField: true, placeholder: 'مثلاً 16:00' });
  fields.push({ fieldLabel: 'روز ' + i + ' — ساعت پایان', fieldType: 'text', requiredField: false, placeholder: 'مثلاً 17:30' });
}

return [{ json: { nDays: n, formDaysJson: JSON.stringify(fields) } }];

return $input.all().map(function (it) {
  var j = Object.assign({}, it.json);
  delete j['_write'];
  delete j['_پیام'];
  return { json: j };
});
